-- Catálogo ampliado: más artículos por subcategoría (con marcas y presentaciones distintas) y tres departamentos nuevos.
-- Electrohogar se vende en San Isidro y Surco; Deportes y aire libre, en Miraflores y Surco.


-- Inventario por sede: stock sano alrededor del inicial y unas pocas filas por agotarse, para que haya qué reponer.
SELECT t.id,
       p.id,
       CASE WHEN (p.id * 13 + t.id) % 83 = 0 THEN 1
            ELSE GREATEST(3, p.initial_stock + ((p.id * 7 + t.id * 3) % 9) - 4) END,
       GREATEST(2, p.initial_stock / 4),
       GREATEST(4, p.initial_stock)
FROM tiendas t
CROSS JOIN products p
WHERE NOT EXISTS (SELECT 1 FROM inventario i WHERE i.producto_id = p.id)
  AND (p.category NOT IN ('Electrohogar', 'Deportes y aire libre')
       OR (p.category = 'Electrohogar' AND t.codigo IN ('T02', 'T03'))
       OR (p.category = 'Deportes y aire libre' AND t.codigo IN ('T01', 'T03')));

UPDATE products p SET stock = COALESCE((SELECT SUM(i.stock) FROM inventario i WHERE i.producto_id = p.id), 0)
WHERE p.stock = 0 AND p.brand IS NOT NULL;
